argv:
$ErrorActionPreference='Stop'
$root='E:\WebAIBridge-R68-OBSERVABILITY-20261014-GPT6'
$sha='1173e893a0b4ded2f92e27b72e99f36f1a96f2ab'
if(@(& git.exe -C $root status --porcelain=v1 --untracked-files=no).Count -ne 0){throw 'DIRTY_CHECKOUT'}
& git.exe -C $root fetch --quiet --no-tags origin agent/r68-live-chat-observability-20261014
if($LASTEXITCODE -ne 0){throw 'FETCH_FAIL'}
& git.exe -C $root checkout --quiet --detach $sha
if($LASTEXITCODE -ne 0){throw 'CHECKOUT_FAIL'}
$log=Join-Path $root 'R68_RETEST_RESULTS.txt'
Push-Location (Join-Path $root 'app')
try{& node.exe --test r68-live-chat-observability.test.js r68-live-viewer.test.js autonomous-send-gate-r50.test.js r65-global-canary-cap.test.js *> $log; $rc=$LASTEXITCODE}finally{Pop-Location}
Write-Output ('EXACT_HEAD='+(& git.exe -C $root rev-parse HEAD))
Write-Output ('RESULT='+$rc)
Select-String -LiteralPath $log -Pattern '^ℹ (?:tests|pass|fail)|^✖'|Select-Object -Last 12|ForEach-Object{Write-Output $_.Line}
if($rc -ne 0){Write-Output 'FAILURE_DETAILS';Get-Content -LiteralPath $log -Tail 55}
if($rc -ne 0){throw 'R68_RETEST_FAILURE'}
